SELECT hd.hd_income_band_sk, hd.hd_buy_potential, SUM(cr.cr_return_amount) AS total_return_amount, COUNT(sr.sr_ticket_number) AS total_store_returns FROM catalog_returns cr JOIN household_demographics hd ON cr.cr_refunded_hdemo_sk = hd.hd_demo_sk JOIN store_returns sr ON sr.sr_hdemo_sk = hd.hd_demo_sk WHERE cr.cr_returned_date_sk = 2451096 AND sr.sr_returned_date_sk = 2452213 GROUP BY hd.hd_income_band_sk, hd.hd_buy_potential
